group_ids = {
    "santorini": 278,
    "venice": 276,
    "tokyo": 277,
    "seoul": 275
}

group_members = {}
for trip, gid in group_ids.items():
    result = apis.splitwise.show_group(group_id=gid, access_token=splitwise_token)
    print(f"{trip} group {gid}: {result}")
    group_members[trip] = result.get("members", [])

