steps.code:
# Let's verify the recorded expenses by fetching them for each group.
# We'll use page_limit=20 to get all expenses in one page.
for trip, gid in group_ids.items():
    result = apis.splitwise.show_group_expenses(
        group_id=gid,
        access_token=splitwise_token,
        page_limit=20
    )
    print(f"\n=== {trip} (group {gid}) ===")
    if isinstance(result, list):
        for exp in result:
            print(f"  ID: {exp['expense_id']}, Desc: {exp['description']}, Amount: {exp['paid_amount']}, Payer: {exp['payer']['email']}")
            print(f"    Debtors: {[s['debtor']['email'] for s in exp['shares']]}")
    else:
        print(result)

